/**
 * Laundry Module Solver for Keep Talking and Nobody Explains
 *
 * Paste this game's manual once (text or pictures: its formulas change every game), then the bot
 * message for each load (text or a screenshot). The captured counts and the serial give the item,
 * material and colour, and from them the Wash, Dry, Iron and Special care settings — with how many
 * presses each button needs (load 1 always starts on 30°C, High heat, 150°C, Bleach).
 */
(function () {
  'use strict';

  // ── Reading and solving: bomb_boomed's (window.BombLogic.laundry, bomb-logic.js) ──
  // Generated by bomb_boomed's scripts/build-conso-logic.mjs: re-run it to sync, don't copy code here.
  const {
    readLaundryPicture, solveLaundry, pressesFor, parseLaundryText, parseLaundryManual, describeFormula,
    CONTROLS, TABLES, SAMPLE_MANUAL_TEXT, SPRITE, SPRITE_CELL
  } = window.BombLogic.laundry;
  const preWarmOCR = window.BombLogic.search.preWarmOCR;
  const K = window.ModuleKit;
  const { $, esc } = K;

  const COUNT_FIELDS = [['remaining', 'Remaining'], ['solved', 'Solved'], ['needy', 'Needy'], ['total', 'Total']];
  const EMPTY = { remaining: '', solved: '', needy: '', total: '' };
  const SAMPLE_TEXT = 'Load 1. Set wash, dry, iron and special care using the helper manual.\nCaptured counts: 7 remaining, 0 solved, 1 needy, 8 total. Serial: LROOXIWG.\nCheck in 50 seconds.';
  const START = { wash: CONTROLS[0][2][0], dry: CONTROLS[1][2][0], iron: CONTROLS[2][2][0], care: CONTROLS[3][2][0] };

  const state = {
    manualText: '',   // this game's manual
    counts: { ...EMPTY },
    load: null,
    current: null,    // symbols the tiles show now (from a picture)
    unsure: [],
    status: { text: '', ok: null },
    busy: false,
    thumb: '',
    checkAt: null
  };
  window.laundryModuleState = state;
  let checkTimer = null;

  function injectStyles() {
    K.injectBase();
    if ($('laundryStyles')) return;
    const style = document.createElement('style');
    style.id = 'laundryStyles';
    style.textContent = `
    .ld-sym { display: inline-block; flex: none; background-color: #f1f1f1; background-repeat: no-repeat; border-radius: 6px; }
    .ld-sym-none { display: inline-flex; align-items: center; justify-content: center; color: #111; font-weight: 800; }
    .ld-tags { display: flex; flex-wrap: wrap; gap: 5px; margin: -4px 0 10px; }
    .ld-tag { font: 11px 'JetBrains Mono', ui-monospace, monospace; padding: 2px 7px; border-radius: 6px; border: 1px solid #2d3366; color: #cbd5e1; }
    .ld-tag.ok { border-color: rgba(74,222,128,.5); color: #a7f3c0; }
    .ld-tag.bad { border-color: rgba(255,95,87,.5); color: #ff9b94; }
    .ld-tag.warn { border-color: rgba(255,216,117,.5); color: #ffd875; }
    .ld-facts { display: flex; flex-wrap: wrap; gap: 8px; align-items: flex-end; }
    .ld-facts label { display: flex; flex-direction: column; gap: 3px; }
    .ld-facts input { width: 76px; }
    .ld-facts input.serial { width: 110px; text-transform: uppercase; }
    .ld-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; margin-bottom: 12px; }
    @media (max-width: 600px) { .ld-grid { grid-template-columns: minmax(0, 1fr); } }
    .ld-card { background: #070814; border: 1px solid #1c2042; border-radius: 12px; padding: 10px 12px; }
    .ld-card-head { font: 800 11px 'Outfit', sans-serif; color: #ffd875; letter-spacing: 1px; margin-bottom: 6px; }
    .ld-card-row { display: flex; gap: 10px; align-items: center; }
    .ld-card-txt { display: flex; flex-direction: column; gap: 2px; min-width: 0; font-size: 13px; }
    .ld-press { color: #4ade80; font-weight: 700; font-size: 12px; }
    .ld-press.zero { color: #8892b0; }
    .ld-why { color: #8892b0; font-size: 11px; }
    .ld-current { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-top: 10px; }
    .ld-cur { display: inline-flex; align-items: center; gap: 4px; }
    .ld-cur.unsure select { border-color: #ef4444; }
    .ld-work div { margin-bottom: 4px; font-size: 12px; line-height: 1.6; }
    `;
    document.head.appendChild(style);
  }

  /** One care symbol, cut from the helper's sheet. */
  function careSymbol(control, name, size = 40) {
    const row = CONTROLS.findIndex(c => c[0] === control);
    const col = row >= 0 ? CONTROLS[row][2].indexOf(name) : -1;
    if (col < 0) return `<span class="ld-sym ld-sym-none" style="width:${size}px;height:${size}px">?</span>`;
    const k = size / SPRITE_CELL;
    return `<span class="ld-sym" title="${esc(name)}" style="width:${size}px;height:${size}px;background-image:url(${SPRITE});background-size:${12 * SPRITE_CELL * k}px ${4 * SPRITE_CELL * k}px;background-position:-${col * size}px -${row * size}px"></span>`;
  }

  function renderUI() {
    const section = $('laundrySection');
    if (!section) return;
    section.innerHTML = `
      <div class="mk-shell">
        <div class="mk-head">
          <div class="mk-title"><span>🧺</span> Laundry Solver <span class="mk-pill">Wash · Dry · Iron · Care</span></div>
          <div class="mk-actions">
            <button class="mk-btn" type="button" data-act="clear">Clear</button>
            <button class="mk-btn gold" type="button" data-act="next" title="Keep the manual, serial and symbols; clear the counts for the next load">↻ Next load</button>
            <button class="mk-btn" type="button" data-act="clear-manual" id="laundryClearManual" title="New game: forget this game's manual">Clear manual</button>
            <button class="mk-btn gold" type="button" data-act="sample">⚡ Sample</button>
          </div>
        </div>
        <div class="mk-layout">
          <div>
            <div class="mk-card">
              <div class="mk-card-title">Paste Pictures</div>
              <input type="file" id="laundryFileInput" accept="image/*" multiple style="display:none;">
              <div id="laundryDropzone" class="mk-dropzone">
                <div class="mk-drop-icon" id="laundryDropIcon">🧺 30° ⊡ ▵</div>
                <div class="mk-drop-title">Click, drop or <kbd>Ctrl+V</kbd> the manual (once per game) and the module picture</div>
                <div class="mk-drop-sub">pictures of the <b>manual</b> (both pages at once is fine), the <b>module</b>, or a screenshot of the whole <b>message</b> · text goes in the boxes below</div>
              </div>
              <div id="laundryStatus"></div>
              <label class="mk-label" for="laundryManual">Helper manual (once per game — its formulas change every game)</label>
              <textarea id="laundryManual" class="mk-textarea" spellcheck="false" placeholder="Paste the Laundry manual's text here, or paste pictures of it above.&#10;Item = remaining + 3&#10;Material = solved + needy + 5&#10;Color = last serial digit + total + 3 (no digit: use 0)&#10;…"></textarea>
              <div id="laundryManualSum"></div>
              <label class="mk-label" for="laundryMsg">Bot message (each load, paste as-is)</label>
              <textarea id="laundryMsg" class="mk-textarea" spellcheck="false" placeholder="Load 1. Set wash, dry, iron and special care using the helper manual.&#10;Captured counts: 7 remaining, 0 solved, 1 needy, 8 total. Serial: LROOXIWG."></textarea>
              <div class="ld-facts">
                ${COUNT_FIELDS.map(([k, lbl]) => `<label><span class="mk-label">${lbl}</span><input type="number" min="0" inputmode="numeric" class="mk-input" id="laundryCount-${k}" data-count="${k}" placeholder="—"></label>`).join('')}
                <label><span class="mk-label">Serial (all bombs)</span><input type="text" class="mk-input serial" id="laundrySerialInput" placeholder="LROOXIWG" spellcheck="false" autocomplete="off"></label>
                <span id="laundryThumb"></span>
              </div>
            </div>
          </div>
          <div>
            <div class="mk-banner">
              <div class="mk-banner-row">
                <div>
                  <div class="mk-banner-lbl" id="laundryAnswerLbl">Set</div>
                  <div id="laundryAnswer" class="mk-answer lines"></div>
                  <div id="laundryStats" class="mk-stats"></div>
                </div>
                <button id="laundryCopyBtn" class="mk-btn gold" type="button" data-act="copy">📋 Copy</button>
              </div>
            </div>
            <div id="laundryGrid"></div>
            <div id="laundryNote"></div>
            <details class="mk-details">
              <summary>How the load was found · the tiles' current symbols</summary>
              <div id="laundryWork"></div>
              <div class="ld-current"><span class="mk-label">Tiles show now:</span><span id="laundryTiles" style="display:contents"></span></div>
            </details>
          </div>
        </div>
      </div>`;
    $('laundrySerialInput').value = K.savedSerial();
    K.wirePictures({ sectionId: 'laundrySection', dropzoneId: 'laundryDropzone', inputId: 'laundryFileInput', onPictures: readPictures });
    $('laundryManual').addEventListener('input', (e) => { state.manualText = e.target.value; update(); });
    $('laundryMsg').addEventListener('input', (e) => handleText(e.target.value));
    $('laundrySerialInput').addEventListener('input', () => update()); // typed here or pushed by the serial bar
    section.addEventListener('input', (e) => {
      const k = e.target.dataset && e.target.dataset.count;
      if (k) { state.counts = { ...state.counts, [k]: e.target.value }; update(); }
    });
    section.addEventListener('click', onClick);
    section.addEventListener('change', onChange);
    update();
  }

  const serial = () => ($('laundrySerialInput')?.value || '').trim();
  function setSerial(v) {
    const el = $('laundrySerialInput');
    if (!el || !v) return;
    el.value = v;
    el.dispatchEvent(new Event('input', { bubbles: true })); // the serial bar takes it for every module
  }
  function showCounts() { for (const [k] of COUNT_FIELDS) { const el = $(`laundryCount-${k}`); if (el) el.value = state.counts[k]; } }
  function setManual(text) { state.manualText = text; $('laundryManual').value = text; }

  /** Counts, serial, load and check time from a bot message (typed or read from a picture). */
  function takeFacts(f, from) {
    const next = {};
    for (const [k] of COUNT_FIELDS) if (f[k] != null) next[k] = String(f[k]);
    if (Object.keys(next).length) { state.counts = { ...state.counts, ...next }; showCounts(); }
    if (f.serial) setSerial(f.serial);
    if (f.load != null) state.load = f.load;
    if (f.checkIn != null) startCheck(Date.now() + f.checkIn * 1000);
    const got = Object.keys(next).length + (f.serial ? 1 : 0);
    return got ? `${from}: ${COUNT_FIELDS.filter(([k]) => next[k] != null).map(([k]) => `${next[k]} ${k}`).join(', ')}${f.serial ? ` · serial ${f.serial}` : ''}` : '';
  }

  function handleText(text) {
    const msg = takeFacts(parseLaundryText(text), '✓ Message');
    state.status = msg ? { text: msg, ok: true } : { text: text.trim() ? 'No counts found in that text yet.' : '', ok: text.trim() ? false : null };
    update();
  }

  // A manual picture with the formulas starts the manual over (page 1 / a new game); one without
  // them (page 2) is added to what is there.
  function addManualText(text, hasFormulas) {
    setManual(hasFormulas || !state.manualText.trim() ? text : `${state.manualText.trim()}\n\n${text}`);
  }

  async function readPictures(items) {
    state.busy = true;
    update();
    const notes = [];
    let bad = false;
    const manuals = [];
    for (const { img, uri } of items) {
      try {
        const r = await readLaundryPicture(img, (t) => { state.status = { text: t, ok: null }; showStatus(); });
        if (!r.ok) { notes.push(`⚠ ${r.reason || 'Not a Laundry picture.'}`); bad = true; continue; }
        if (r.type === 'manual') { manuals.push(r); continue; }
        if (r.type === 'message') { const f = takeFacts(r.facts, '✓ Message'); notes.push(f || '⚠ No counts found in that picture'); if (!f) bad = true; continue; }
        state.thumb = uri || '';
        state.current = r.symbols.current;
        state.unsure = r.symbols.sure ? [] : Object.entries(r.symbols.scores || {}).filter(([, v]) => v.score < 0.6 || v.margin < 0.04).map(([k]) => k);
        const sym = CONTROLS.map(([k]) => r.symbols.current[k] || '?').join(' / ');
        const facts = r.facts ? takeFacts(r.facts, 'message') : '';
        notes.push(`✓ Module shows ${sym}${facts ? ` · ${facts}` : r.text ? ' · counts not found in the text — type them' : ''}`);
        if (!r.symbols.sure) bad = true;
      } catch (e) {
        notes.push(`⚠ ${e.message || 'Could not read that picture.'}`);
        bad = true;
      }
    }
    // page 1 (formulas) before page 2, whatever order they came in
    manuals.sort((a, b) => Object.keys(b.manual.formulas).length - Object.keys(a.manual.formulas).length);
    manuals.forEach((m, i) => addManualText(m.text, i === 0 && Object.keys(m.manual.formulas).length > 0));
    if (manuals.length) notes.push(`✓ Manual text read from ${manuals.length === 1 ? 'the picture' : `${manuals.length} pictures`} — check it in the box`);
    state.busy = false;
    state.status = { text: notes.join('  ·  '), ok: !bad };
    update();
  }

  function startCheck(at) {
    state.checkAt = at;
    clearInterval(checkTimer);
    checkTimer = at ? setInterval(showCheck, 500) : null;
  }
  function showCheck() {
    const el = $('laundryCheck');
    if (!el || !state.checkAt) return;
    const left = Math.max(0, Math.ceil((state.checkAt - Date.now()) / 1000));
    el.innerHTML = `⏱ Next check in <b>${left}s</b>${left === 0 ? ' — it is checking now' : ''}`;
  }

  function onClick(e) {
    const b = e.target.closest('[data-act]');
    if (!b || b.tagName === 'SELECT') return;
    const act = b.dataset.act;
    if (act === 'copy') { K.copyText(solveNow().answer, b, '📋 Copy'); return; }
    if (act === 'next') {
      state.counts = { ...EMPTY }; showCounts();
      state.load = state.load ? state.load + 1 : null;
      $('laundryMsg').value = '';
      // the module picture stays the same through a game's loads: keep the symbols read from it
      startCheck(null);
      state.status = { text: 'Next load — paste its message (the manual, serial and module symbols stay).', ok: null };
    } else if (act === 'clear') {
      state.counts = { ...EMPTY }; showCounts();
      state.load = null; state.current = null; state.unsure = []; state.thumb = '';
      $('laundryMsg').value = '';
      startCheck(null);
      state.status = { text: '', ok: null };
    } else if (act === 'clear-manual') {
      setManual('');
      state.status = { text: 'Manual cleared — paste the new game\'s manual.', ok: null };
    } else if (act === 'sample') {
      setManual(SAMPLE_MANUAL_TEXT);
      state.current = null; state.unsure = [];
      $('laundryMsg').value = SAMPLE_TEXT;
      handleText(SAMPLE_TEXT);
      return;
    } else return;
    update();
  }

  function onChange(e) {
    const k = e.target.dataset.tile;
    if (!k) return;
    state.current = { ...(state.current || START), [k]: e.target.value };
    state.unsure = state.unsure.filter(x => x !== k);
    update();
  }

  function solveNow() {
    const manual = parseLaundryManual(state.manualText);
    const res = solveLaundry(manual, state.counts, serial());
    // presses from what the tiles show; without a picture, from the first symbols. Load 1 always
    // starts there and a press steps to the next symbol in the sheet's order (confirmed by players)
    const startKnown = Boolean(state.current) || state.load === 1;
    const from = state.current || START;
    const presses = res.ready ? pressesFor(res.set, from) : null;
    const pressNote = (k) => (presses && presses[k] ? ` ↻${presses[k]}` : '');
    const answer = res.ready
      ? CONTROLS.map(([k, label]) => `${label === 'Special care' ? 'Care' : label} ${res.set[k]}${startKnown ? pressNote(k) : ''}`).join(' · ')
      : '';
    return { manual, res, startKnown, from, presses, pressNote, answer };
  }

  function showStatus() {
    const el = $('laundryStatus');
    if (el) el.innerHTML = state.status.text ? `<div class="mk-status ${state.status.ok === false ? 'bad' : state.status.ok ? 'ok' : ''}">${esc(state.status.text)}</div>` : '';
  }

  function manualSummary(manual, borrowed) {
    const f = TABLES.filter(k => manual.formulas[k]);
    if (!f.length && !Object.keys(manual.tables).length && !manual.care.length) return '';
    const rows = TABLES.map(k => `${k} ${manual.tables[k] ? manual.tables[k].length : 0}`).join(' · ');
    return `<div class="ld-tags">
      ${manual.load ? `<span class="ld-tag">LOAD ${manual.load}</span>` : ''}
      ${TABLES.map(k => `<span class="ld-tag ${manual.formulas[k] && !manual.formulas[k].unknown ? 'ok' : 'bad'}">${esc(describeFormula(k, manual.formulas[k]))}</span>`).join('')}
      <span class="ld-tag">rows: ${esc(rows)}</span>
      <span class="ld-tag ${manual.care.some(r => r.when.kind === 'unknown') ? 'bad' : ''}">${manual.overrides.length} exceptions · ${manual.care.length} care rules</span>
      ${borrowed && borrowed.length ? `<span class="ld-tag warn">not in the pasted manual, so the usual ${esc(borrowed.join(', '))} (the same in both manuals seen so far)</span>` : ''}
      ${manual.unread.length ? `<span class="ld-tag warn" title="${esc(manual.unread.join('\n'))}">${manual.unread.length} line${manual.unread.length === 1 ? '' : 's'} not understood</span>` : ''}
    </div>`;
  }

  function update() {
    if (!$('laundryAnswer')) return;
    const { manual, res, startKnown, from, presses, pressNote, answer } = solveNow();
    const load = state.load;

    $('laundryDropIcon').textContent = state.busy ? '⏳' : '🧺 30° ⊡ ▵';
    showStatus();
    $('laundryClearManual').disabled = !state.manualText;
    $('laundryManualSum').innerHTML = manualSummary(manual, res.ready ? res.borrowed : [])
      + (manual.load && load && manual.load !== load ? `<div class="mk-note">The manual is for load ${manual.load}, the message is load ${load} — if this load's manual is different, paste it.</div>` : '');
    $('laundryThumb').innerHTML = state.thumb ? `<img class="mk-thumb" src="${state.thumb}" alt="module">` : '';

    const placeholder = state.busy ? '📷 READING…'
      : res.missing && res.missing.includes('manual') ? "PASTE THIS GAME'S LAUNDRY MANUAL"
      : res.missing && res.missing.length ? `NEED ${res.missing.map(m => m.toUpperCase()).join(', ')}`
      : res.reason ? res.reason.toUpperCase() : '— — —';
    $('laundryAnswerLbl').textContent = load ? `Set — load ${load}` : 'Set';
    $('laundryAnswer').innerHTML = res.ready
      ? CONTROLS.map(([k, label]) => `<div>${esc(label)}: ${esc(res.set[k])}${esc(pressNote(k))}</div>`).join('')
      : `<span class="ph">${esc(placeholder)}</span>`;
    $('laundryStats').textContent = res.ready ? `${res.item.name} · ${res.material.name} · ${res.color.name}${load ? ` · load ${load}` : ''}` : 'Item · material · color';
    $('laundryCopyBtn').disabled = !answer;

    $('laundryGrid').innerHTML = res.ready ? `<div class="ld-grid">${CONTROLS.map(([k, label]) => `
      <div class="ld-card">
        <div class="ld-card-head">${esc(label.toUpperCase())}</div>
        <div class="ld-card-row">
          ${careSymbol(k, res.set[k], 48)}
          <div class="ld-card-txt">
            <b>${esc(res.set[k])}</b>
            <span class="ld-press ${presses[k] ? '' : 'zero'}">${presses[k] == null ? '' : presses[k] ? `press ${presses[k]}×` : 'already set'}${!startKnown && presses[k] ? ' *' : ''}</span>
            <span class="ld-why">${esc(res.why[k])}</span>
          </div>
        </div>
      </div>`).join('')}</div>` : '';

    $('laundryNote').innerHTML = res.ready ? `<div class="mk-note">${
      state.current
        ? `Presses count from the symbols in the picture${state.unsure.length ? ` — <b>not sure about ${esc(state.unsure.join(', '))}</b>, check them under "How the load was found"` : ''}; each press steps to the next symbol in the sheet's order.`
        : startKnown
          ? 'Load 1 always starts on 30°C, High heat, 150°C, Bleach; each press steps to the next symbol in the sheet\'s order.'
          : '* Presses count from 30°C, High heat, 150°C, Bleach (how load 1 starts); each press steps to the next symbol in the sheet\'s order. Paste the module picture to count from what it shows now.'
    }${state.checkAt ? '<div id="laundryCheck" style="margin-top:6px;"></div>' : ''}</div>` : '';
    showCheck();

    $('laundryWork').innerHTML = res.ready ? `<div class="ld-work">${TABLES.map(k => `
      <div><b>${k[0].toUpperCase() + k.slice(1)}</b> = ${esc(res.why[k])} → <b>${esc(res[k].name)}</b>${manual.tables[k] ? ` <span class="mk-dim">(${esc(manual.tables[k].map(x => x.name).join(', '))})</span>` : ''}</div>`).join('')}
      <div class="mk-dim">numbers past ${res.modulus - 1} lose ${res.modulus} until they are 0–${res.modulus - 1} · 0 = first in the list</div></div>`
      : `<div class="mk-dim">${!Object.keys(manual.formulas).length ? "Paste this game's manual, then the bot message (or type the counts and the serial)." : 'Paste the bot message (or type the counts and the serial).'}</div>`;

    $('laundryTiles').innerHTML = CONTROLS.map(([k, label, list]) => `
      <label class="ld-cur ${state.unsure.includes(k) ? 'unsure' : ''}">${careSymbol(k, from[k], 28)}
        <select class="mk-select" data-tile="${k}" title="${esc(label)}: the symbol the tile shows now">${list.map(n => `<option${n === from[k] ? ' selected' : ''}>${esc(n)}</option>`).join('')}</select>
      </label>`).join('');
  }

  window.initLaundryModule = function () {
    injectStyles();
    renderUI();
    if (typeof preWarmOCR === 'function') preWarmOCR();
  };
})();
